// Helper function to get tax rates by NCM
export function getNCMTaxRates(ncm: string): NCMTaxEntry | null {
  return NCM_TAX_DATABASE[ncm] || null;
}

// Helper function to get chapter description
export function getChapterDescription(ncm: string): string {
  const chapter = ncm.substring(0, 2);
  const chapters: Record<string, string> = {
    "39": "Plastics and articles thereof",
    "52": "Cotton",
    "63": "Other made-up textile articles"
  };
  return chapters[chapter] || "Unknown Chapter";
}

// Get all NCMs for a specific chapter
export function getNCMsByChapter(chapter: string): string[] {
  return Object.keys(NCM_TAX_DATABASE).filter(ncm => ncm.startsWith(chapter));
}

// Search NCM by partial code or description
export function searchNCM(query: string, limit: number = 20): string[] {
  const lowerQuery = query.toLowerCase();
  return Object.entries(NCM_TAX_DATABASE)
    .filter(([ncm, data]) => 
      ncm.includes(query) || 
      data.description.toLowerCase().includes(lowerQuery)
    )
    .map(([ncm]) => ncm)
    .slice(0, limit);
}
